import React, { useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import "./styles.css";

const API_BASE = (import.meta.env.VITE_API_URL ?? "http://127.0.0.1:8000").replace(/\/$/, "");
const api = (path) => `${API_BASE}${path}`;

const EXAMPLES = [
  "Which city generated the highest revenue?",
  "What are the top 4 cities with highest revenue?",
  "What is the total revenue generated by each city?",
  "Generate a line chart for revenue over time",
  "Generate a pie chart for revenue by city",
  "Show a histogram of revenue",
  "Show me 10 rows of the dataset",
];

const CHART_LABELS = {
  bar: "Bar chart", line: "Line chart", pie: "Pie chart",
  histogram: "Histogram", kpi: "KPI", table: "Table",
};

function formatValue(value) {
  if (typeof value === "number") {
    return Number.isInteger(value)
      ? value.toLocaleString("en-IN")
      : value.toLocaleString("en-IN", { maximumFractionDigits: 2 });
  }
  if (value == null) return "—";
  return String(value);
}

function numericColumnIndexes(execution) {
  const columns = execution?.columns || [];
  const rows = execution?.rows || [];
  return columns.map((column, index) => ({ column, index })).filter(({ index }) => {
    const values = rows.map((row) => row[index]).filter((value) => value != null);
    return values.length > 0 && values.every((value) => value !== "" && Number.isFinite(Number(value)));
  });
}

function chartOptions(execution) {
  const numeric = numericColumnIndexes(execution);
  const columns = execution?.columns || [];
  const categories = columns.filter((column) => !numeric.some((item) => item.column === column));
  const options = ["table"];
  if (numeric.length) options.push("histogram");
  if (numeric.length && categories.length) {
    options.push("bar", "line");
    const firstNumericIndex = numeric[0].index;
    const pieValues = (execution?.rows || []).map((row) => Number(row[firstNumericIndex])).filter(Number.isFinite);
    if (pieValues.length && pieValues.every((value) => value >= 0) && pieValues.reduce((sum, value) => sum + value, 0) > 0) options.push("pie");
  }
  if (execution?.rows?.length === 1 && numeric.length) options.push("kpi");
  return [...new Set(options)];
}

function ResultTable({ execution, compact = false }) {
  if (!execution?.columns?.length) return <p className="empty-note">No tabular data returned.</p>;
  const rows = execution.rows || [];
  return <div className={`table-scroll ${compact ? "compact" : ""}`}>
    <table className="data-table">
      <thead><tr>{execution.columns.map((column) => <th key={column}>{column.replaceAll("_", " ")}</th>)}</tr></thead>
      <tbody>{rows.map((row, rowIndex) => <tr key={rowIndex}>{execution.columns.map((column, colIndex) => <td key={`${rowIndex}-${column}`}>{formatValue(row[colIndex])}</td>)}</tr>)}</tbody>
    </table>
    {rows.length === 0 && <p className="empty-note">No rows matched this question.</p>}
    {execution.truncated && <p className="table-footnote">The result was capped by the configured row safety limit.</p>}
  </div>;
}

function BarChart({ execution, spec }) {
  const columns = execution.columns || [];
  const rows = execution.rows || [];
  const xi = columns.indexOf(spec.x);
  const seriesKeys = [spec.y, ...(Array.isArray(spec.series) ? spec.series : [])].filter((key) => columns.includes(key));
  if (xi < 0 || !seriesKeys.length || !rows.length) return <p className="empty-note">This result does not contain a category and numeric measure for a bar chart.</p>;
  const series = seriesKeys.map((key) => ({ key, index: columns.indexOf(key), values: rows.map((row) => Number(row[columns.indexOf(key)])) }));
  const allValues = series.flatMap((item) => item.values).filter(Number.isFinite);
  if (!allValues.length) return <p className="empty-note">This result has no numeric values to chart.</p>;
  const maxValue = Math.max(0, ...allValues);
  const minValue = Math.min(0, ...allValues);
  const w = 900, h = 350, left = 78, right = 24, top = 28, bottom = 70;
  const plotW = w - left - right, plotH = h - top - bottom;
  const range = Math.max(maxValue - minValue, 1);
  const zeroY = top + (maxValue / range) * plotH;
  const slot = plotW / rows.length;
  const groupW = Math.min(94, slot * .8);
  const barGap = 3;
  const individualW = Math.max(2, (groupW - barGap * (series.length - 1)) / series.length);
  const colors = ["#596ed8", "#20a083", "#e4a044", "#9a75c8"];
  return <div className="chart-frame"><div className="chart-title">{spec.title}</div>
    {series.length > 1 && <div className="series-legend">{series.map((item, i) => <span key={item.key}><i style={{ background: colors[i % colors.length] }}/>{item.key.replaceAll("_", " ")}</span>)}</div>}
    <svg viewBox={`0 0 ${w} ${h}`} className="chart-svg" role="img" aria-label={spec.title}>
      {[0, .25, .5, .75, 1].map((fraction) => { const y = top + plotH * fraction; const value = maxValue - range * fraction; return <g key={fraction}><line x1={left} x2={w-right} y1={y} y2={y} className="chart-grid"/><text x={left-10} y={y+4} textAnchor="end" className="chart-tick">{formatValue(Math.round(value))}</text></g>; })}
      {rows.map((row, rowIndex) => {
        const label = String(row[xi] ?? "");
        const groupX = left + rowIndex * slot + (slot - groupW) / 2;
        return <g key={`${label}-${rowIndex}`}>
          {series.map((item, seriesIndex) => {
            const value = item.values[rowIndex];
            if (!Number.isFinite(value)) return null;
            const valueY = top + ((maxValue - value) / range) * plotH;
            const y = Math.min(valueY, zeroY);
            const height = Math.max(1, Math.abs(zeroY - valueY));
            const x = groupX + seriesIndex * (individualW + barGap);
            return <rect key={item.key} x={x} y={y} width={individualW} height={height} rx="3" fill={colors[seriesIndex % colors.length]} />;
          })}
          <text x={left + rowIndex * slot + slot/2} y={h-27} textAnchor="middle" className="chart-tick">{label.length > 13 ? `${label.slice(0,12)}…` : label}</text>
        </g>;
      })}
    </svg>
  </div>;
}

function LineChart({ execution, spec }) {
  const columns = execution.columns || [];
  const rows = execution.rows || [];
  const xi = columns.indexOf(spec.x);
  const seriesKeys = [spec.y, ...(Array.isArray(spec.series) ? spec.series : [])].filter((key) => columns.includes(key));
  if (xi < 0 || !seriesKeys.length || rows.length < 2) return <p className="empty-note">A line chart needs a date/category column and at least two numeric observations.</p>;
  const series = seriesKeys.map((key) => ({ key, values: rows.map((row) => Number(row[columns.indexOf(key)])) }));
  const allValues = series.flatMap((item) => item.values).filter(Number.isFinite);
  if (!allValues.length) return <p className="empty-note">No numeric observations were returned for this line chart.</p>;
  const w = 900, h = 350, left = 78, right = 28, top = 28, bottom = 68;
  const min = Math.min(...allValues), max = Math.max(...allValues), range = max-min || 1;
  const x = (index) => left + (index / Math.max(rows.length-1,1)) * (w-left-right);
  const y = (value) => top + ((max-value)/range) * (h-top-bottom);
  const colors = ["#5368d5", "#20a083", "#e4a044", "#9a75c8"];
  return <div className="chart-frame"><div className="chart-title">{spec.title}</div>
    {series.length > 1 && <div className="series-legend">{series.map((item,i) => <span key={item.key}><i style={{background:colors[i % colors.length]}}/>{item.key.replaceAll("_"," ")}</span>)}</div>}
    <svg viewBox={`0 0 ${w} ${h}`} className="chart-svg" role="img" aria-label={spec.title}>
      {[0,.25,.5,.75,1].map((fraction) => { const yy=top+(h-top-bottom)*fraction; return <g key={fraction}><line x1={left} x2={w-right} y1={yy} y2={yy} className="chart-grid"/><text x={left-10} y={yy+4} textAnchor="end" className="chart-tick">{formatValue(max-range*fraction)}</text></g>; })}
      {series.map((item, seriesIndex) => {
        const points = item.values.map((value,index) => ({value,index})).filter((point) => Number.isFinite(point.value));
        const path = points.map((point,index) => `${index===0 ? "M" : "L"} ${x(point.index)} ${y(point.value)}`).join(" ");
        return <g key={item.key}><path d={path} fill="none" stroke={colors[seriesIndex % colors.length]} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>{points.map((point) => <circle key={point.index} cx={x(point.index)} cy={y(point.value)} r="3.5" fill="#fff" stroke={colors[seriesIndex % colors.length]} strokeWidth="2"/>)}</g>;
      })}
      {rows.map((row,index) => { if (!(index===0 || index===rows.length-1 || index===Math.floor(rows.length/2))) return null; const label=String(row[xi] ?? ""); return <text key={index} x={x(index)} y={h-25} textAnchor="middle" className="chart-tick">{label.length>18 ? `${label.slice(0,17)}…` : label}</text>; })}
    </svg>
  </div>;
}

function PieChart({ execution, spec }) {
  const columns = execution.columns || [];
  const rows = execution.rows || [];
  const xi = columns.indexOf(spec.x), yi = columns.indexOf(spec.y);
  const slices = rows.map((row) => ({ label: String(row[xi] ?? ""), value: Number(row[yi]) })).filter((item) => Number.isFinite(item.value) && item.value >= 0);
  const total = slices.reduce((sum, item) => sum + item.value, 0);
  if (!slices.length || total <= 0) return <p className="empty-note">A pie chart needs positive values. Use a bar chart for zero or negative values.</p>;
  const colors = ["#5368d5", "#2c9a83", "#e6a14b", "#9b78cc", "#df7183", "#4d9fca", "#91a84e", "#64748b"];
  let offset = 0;
  const gradient = slices.map((slice, index) => {
    const start = offset;
    offset += (slice.value / total) * 100;
    return `${colors[index % colors.length]} ${start}% ${offset}%`;
  }).join(", ");
  return <div className="chart-frame"><div className="chart-title">{spec.title}</div><div className="pie-layout">
    <div className="pie-donut" style={{ background: `conic-gradient(${gradient})` }}><div className="pie-hole"><strong>{slices.length}</strong><span>categories</span></div></div>
    <div className="pie-legend">{slices.map((slice, index) => <div className="legend-row" key={`${slice.label}-${index}`}>
      <span className="legend-swatch" style={{ background: colors[index % colors.length] }}/><span className="legend-name">{slice.label}</span>
      <strong>{((slice.value / total) * 100).toFixed(1)}%</strong><small>{formatValue(slice.value)}</small>
    </div>)}</div>
  </div></div>;
}

function Histogram({ execution, spec }) {
  const columns = execution.columns || [];
  const rows = execution.rows || [];
  let index = columns.indexOf(spec.x);
  let values = index >= 0 ? rows.map((row) => Number(row[index])).filter(Number.isFinite) : [];
  if (!values.length) {
    const fallback = numericColumnIndexes(execution)[0];
    index = fallback?.index ?? -1;
    values = index >= 0 ? rows.map((row) => Number(row[index])).filter(Number.isFinite) : [];
  }
  if (!values.length) return <p className="empty-note">No numeric observations were returned for this histogram.</p>;
  const min = Math.min(...values), max = Math.max(...values);
  const binCount = Math.min(20, Math.max(3, Math.round(Math.sqrt(values.length))));
  const width = (max - min) || 1;
  const counts = Array(binCount).fill(0);
  values.forEach((value) => {
    const bin = Math.min(binCount - 1, Math.floor(((value - min) / width) * binCount));
    counts[bin] += 1;
  });
  const maxCount = Math.max(...counts, 1);
  const w = 820, h = 320, left = 66, right = 24, top = 24, bottom = 56;
  const plotW = w - left - right, plotH = h - top - bottom;
  const slot = plotW / binCount, barW = slot * .78;
  return <div className="chart-frame"><div className="chart-title">{spec.title} · {values.length} observations</div>
    <svg viewBox={`0 0 ${w} ${h}`} className="chart-svg" role="img" aria-label={spec.title}>
      {[0, .5, 1].map((fraction) => { const yy = top + plotH * (1 - fraction); return <g key={fraction}><line x1={left} x2={w - right} y1={yy} y2={yy} className="chart-grid"/><text x={left - 10} y={yy + 4} textAnchor="end" className="chart-tick">{Math.round(maxCount * fraction)}</text></g>; })}
      {counts.map((count, i) => { const bh = (count / maxCount) * plotH; const x = left + i * slot + (slot - barW) / 2; const y = top + plotH - bh; const from = min + (i / binCount) * width; const to = min + ((i + 1) / binCount) * width; return <g key={i}><rect x={x} y={y} width={barW} height={bh} rx="4" className="bar-fill"/><text x={x + barW / 2} y={y - 6} textAnchor="middle" className="chart-value">{count}</text>{(i === 0 || i === binCount - 1 || i === Math.floor(binCount / 2)) && <text x={x + barW / 2} y={h - 23} textAnchor="middle" className="chart-tick">{formatValue(from)}–{formatValue(to)}</text>}</g>; })}
    </svg>
  </div>;
}

function KpiCard({ execution, spec }) {
  const columns = execution.columns || [];
  const rows = execution.rows || [];
  if (!rows.length) return <p className="empty-note">No value to display.</p>;
  const yi = spec?.y ? columns.indexOf(spec.y) : rows[0].findIndex((value) => typeof value === "number");
  const preferredCategory = spec?.x ? columns.indexOf(spec.x) : -1;
  const category = preferredCategory >= 0 && preferredCategory !== yi
    ? preferredCategory
    : columns.findIndex((_, index) => index !== yi);
  return <div className="kpi-visual"><span className="kpi-label">{spec?.title || columns[yi] || "Key result"}</span><strong>{formatValue(rows[0][yi])}</strong>{category >= 0 && <span className="kpi-context">{formatValue(rows[0][category])}</span>}</div>;
}

function Visualization({ result }) {
  const execution = result?.execution;
  const spec = result?.visualization;
  const options = useMemo(() => chartOptions(execution), [execution]);
  const [selected, setSelected] = useState(spec?.chart_type || "table");
  useEffect(() => setSelected(spec?.chart_type || "table"), [spec?.chart_type, execution]);
  if (!execution || !spec) return null;
  const displaySpec = { ...spec, chart_type: selected };
  return <section className="visual-section">
    <div className="section-heading"><div><p className="section-eyebrow">EXPLORE THE RESULT</p><h3>Visualization</h3></div>
      <label className="chart-picker">Chart type<select value={selected} onChange={(event) => setSelected(event.target.value)}>{options.map((option) => <option key={option} value={option}>{CHART_LABELS[option]}</option>)}</select></label>
    </div>
    {selected === "bar" ? <BarChart execution={execution} spec={displaySpec} />
      : selected === "line" ? <LineChart execution={execution} spec={displaySpec} />
      : selected === "pie" ? <PieChart execution={execution} spec={displaySpec} />
      : selected === "histogram" ? <Histogram execution={execution} spec={displaySpec} />
      : selected === "kpi" ? <KpiCard execution={execution} spec={displaySpec} />
      : <ResultTable execution={execution} />}
  </section>;
}

function ResultDetails({ result }) {
  if (!result || result.status !== "success") return null;
  return <div className="details-stack">
    <details className="detail-panel"><summary>Returned data <span>{result.execution?.row_count ?? 0} rows</span></summary><ResultTable execution={result.execution} /></details>
    <details className="detail-panel"><summary>Generated SQL</summary><pre className="code-block">{result.sql || "No SQL available"}</pre><button className="small-button" onClick={() => navigator.clipboard?.writeText(result.sql || "")}>Copy SQL</button></details>
    <details className="detail-panel"><summary>Analysis trace</summary><pre className="json-block">{JSON.stringify(result.analysis_trace || {}, null, 2)}</pre></details>
    <details className="detail-panel"><summary>Request metrics</summary><div className="metrics-grid">{Object.entries(result.metrics || {}).map(([key, value]) => <div className="metric-item" key={key}><span>{key.replaceAll("_", " ")}</span><strong>{typeof value === "object" ? JSON.stringify(value) : String(value ?? "—")}</strong></div>)}</div></details>
  </div>;
}

function DatabaseExplorer({ profile }) {
  const [previews, setPreviews] = useState({});
  const [previewLoading, setPreviewLoading] = useState({});
  const [previewErrors, setPreviewErrors] = useState({});

  async function loadPreview(tableName) {
    setPreviewLoading((current) => ({ ...current, [tableName]: true }));
    setPreviewErrors((current) => ({ ...current, [tableName]: "" }));
    try {
      const response = await fetch(
        api(`/api/database/tables/${encodeURIComponent(tableName)}/preview?limit=5`)
      );
      const data = await response.json();
      if (!response.ok) throw new Error(data.detail || "Could not preview this table.");
      setPreviews((current) => ({ ...current, [tableName]: data }));
    } catch (error) {
      setPreviewErrors((current) => ({ ...current, [tableName]: error.message }));
    } finally {
      setPreviewLoading((current) => ({ ...current, [tableName]: false }));
    }
  }

  if (!profile?.tables?.length) return <div className="database-explorer"><p className="empty-note">No database catalog is available yet. Connect a database to inspect its structure.</p></div>;
  return <div className="database-explorer">
    <div className="explorer-summary">
      <strong>{profile.table_count} tables / views discovered</strong>
      <span>{profile.relationships?.length || 0} relationships</span>
    </div>
    <p className="explorer-intro">The assistant discovers every accessible table, its columns and key relationships. Preview a few rows from any table to inspect its contents.</p>
    {profile.tables.map((table) => <details className="explorer-table" key={table.name}>
      <summary><span>{table.name}</span><small>{table.kind} · {table.column_count} columns</small></summary>
      <div className="explorer-columns">
        {table.columns.map((column) => <div className="explorer-column" key={`${table.name}.${column.name}`}>
          <span className="explorer-column-name">{column.name}</span>
          <span className="explorer-column-type">{column.type}</span>
          <span className="explorer-tags">
            {column.primary_key && <em>PK</em>}
            {(column.foreign_keys || []).map((fk) => <em key={`${fk.table}.${fk.column}`} title={`References ${fk.table}.${fk.column}`}>FK</em>)}
          </span>
        </div>)}
      </div>
      <div className="explorer-preview-actions">
        <button type="button" className="small-button" disabled={previewLoading[table.name]} onClick={() => loadPreview(table.name)}>
          {previewLoading[table.name] ? "Loading preview…" : previews[table.name] ? "Refresh 5-row preview" : "Preview 5 rows"}
        </button>
        {previewErrors[table.name] && <p className="explorer-preview-error">{previewErrors[table.name]}</p>}
      </div>
      {previews[table.name] && <div className="explorer-preview">
        <div className="explorer-preview-heading"><strong>Sample rows · {table.name}</strong><span>{previews[table.name].row_count} shown{previews[table.name].truncated ? " · more rows exist" : ""}</span></div>
        <ResultTable execution={previews[table.name]} compact />
      </div>}
    </details>)}
    {!!profile.relationships?.length && <div className="explorer-relations">
      <strong>Discovered relationships</strong>
      {profile.relationships.map((relationship, index) => <p key={`${relationship.from_table}-${relationship.to_table}-${index}`}>
        {relationship.from_table}.{relationship.from_column} <span>→</span> {relationship.to_table}.{relationship.to_column}
      </p>)}
    </div>}
    <p className="explorer-footnote">Schema discovery covers every accessible table and view. Table previews are limited to five rows and only load when requested; the assistant runs read-only queries against the selected database.</p>
  </div>;
}

function DatabaseDialog({ open, onClose, onConnected, currentDatabase }) {
  const [connectionUrl, setConnectionUrl] = useState("");
  const [kind, setKind] = useState("sqlite");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [showUrl, setShowUrl] = useState(false);
  if (!open) return null;

  const examples = {
    sqlite: "sqlite:///C:/Users/your-name/Documents/sales.db",
    postgresql: "postgresql+psycopg://username:password@localhost:5432/database_name",
    mysql: "mysql+pymysql://username:password@localhost:3306/database_name",
  };

  async function connect(event) {
    event.preventDefault();
    setBusy(true); setError("");
    try {
      const response = await fetch(api("/api/database/connect"), {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ connection_url: connectionUrl.trim() }),
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.detail || "Database connection failed.");
      onConnected(data.database);
      setConnectionUrl("");
      onClose();
    } catch (err) {
      setError(err.message || "Could not connect to the database.");
    } finally { setBusy(false); }
  }

  async function useDemo() {
    setBusy(true); setError("");
    try {
      const response = await fetch(api("/api/database/reset"), { method: "POST" });
      const data = await response.json();
      if (!response.ok) throw new Error(data.detail || "Could not restore the demo database.");
      onConnected(data.database); setConnectionUrl(""); onClose();
    } catch (err) { setError(err.message || "Could not restore the demo database."); }
    finally { setBusy(false); }
  }

  return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
    <section className="database-modal" role="dialog" aria-modal="true" aria-labelledby="database-modal-title">
      <div className="modal-header"><div><p className="section-eyebrow">DATA SOURCE</p><h2 id="database-modal-title">Connect a database</h2><p>Connect a database that this backend machine can reach.</p></div><button className="icon-button" onClick={onClose} aria-label="Close">×</button></div>
      <div className="current-source"><span className="source-dot"/><div><small>Currently connected</small><strong>{currentDatabase?.display_name || "Checking database…"}</strong><span>{currentDatabase?.database_type || "—"} · {currentDatabase?.is_demo ? "Sample data" : "Custom connection"}</span></div></div>
      <form onSubmit={connect} className="database-form">
        <label>Database type<select value={kind} onChange={(event) => { setKind(event.target.value); setConnectionUrl(""); }}><option value="sqlite">SQLite database file</option><option value="postgresql">PostgreSQL</option><option value="mysql">MySQL</option></select></label>
        <label>SQLAlchemy connection URL<div className="secret-input"><input required type={showUrl ? "text" : "password"} value={connectionUrl} onChange={(event) => setConnectionUrl(event.target.value)} placeholder={examples[kind]} autoComplete="off"/><button type="button" onClick={() => setShowUrl((value) => !value)}>{showUrl ? "Hide" : "Show"}</button></div></label>
        <p className="field-hint">{kind === "sqlite" ? "Use an absolute path to an existing .db or .sqlite file. Example: sqlite:///C:/data/sales.db" : kind === "postgresql" ? "The backend needs network access and a read-only database user. URL-encode special characters in the password." : "The backend needs network access and a read-only database user. URL-encode special characters in the password."}</p>
        {error && <div className="form-error">{error}</div>}
        <div className="modal-actions"><button type="button" className="button-secondary" onClick={useDemo} disabled={busy}>Restore default database</button><button className="button-primary" disabled={busy || !connectionUrl.trim()}>{busy ? "Connecting…" : "Test & connect"}</button></div>
      </form>
      <div className="security-note"><strong>Connection security</strong><p>The connection URL is sent to your backend and kept in server memory only. It is not saved in browser storage or returned by the API. Use a read-only database account. Restarting the backend restores the configured default database.</p></div>
    </section>
  </div>;
}

function App() {
  const [question, setQuestion] = useState("");
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [apiStatus, setApiStatus] = useState("checking");
  const [config, setConfig] = useState(null);
  const [database, setDatabase] = useState(null);
  const [databaseProfile, setDatabaseProfile] = useState(null);
  const [showExplorer, setShowExplorer] = useState(false);
  const [showContext, setShowContext] = useState(false);
  const [showDatabaseDialog, setShowDatabaseDialog] = useState(false);
  const [context, setContext] = useState(null);
  const [sessionId, setSessionId] = useState(() => {
    const stored = window.localStorage.getItem("nlbi-session-id");
    if (stored) return stored;
    const created = window.crypto?.randomUUID?.() || `session-${Date.now()}`;
    window.localStorage.setItem("nlbi-session-id", created);
    return created;
  });

  async function refreshConnection() {
    try {
      const [healthResponse, configResponse, databaseResponse, contextResponse, profileResponse] = await Promise.all([
        fetch(api("/health")), fetch(api("/api/config")), fetch(api("/api/database")),
        fetch(api("/api/context")), fetch(api("/api/database/profile")),
      ]);
      const [health, info, db, businessContext, profile] = await Promise.all([
        healthResponse.json(), configResponse.json(), databaseResponse.json(),
        contextResponse.json(), profileResponse.json(),
      ]);
      setApiStatus(health.status === "ok" ? "online" : "degraded");
      setConfig(info); setDatabase(db); setContext(businessContext); setDatabaseProfile(profile);
    } catch { setApiStatus("offline"); }
  }

  useEffect(() => { refreshConnection(); }, []);
  const successfulCount = useMemo(() => messages.filter((message) => message.result?.status === "success").length, [messages]);

  async function askQuestion(value = question) {
    const clean = value.trim();
    if (!clean || loading) return;
    setLoading(true); setError(""); setQuestion("");
    try {
      const response = await fetch(api("/ask"), {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question: clean, session_id: sessionId }),
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.detail || `Request failed (${response.status}).`);
      if (data.session_id && data.session_id !== sessionId) {
        setSessionId(data.session_id); window.localStorage.setItem("nlbi-session-id", data.session_id);
      }
      setMessages((prev) => [...prev, { role: "user", content: clean }, { role: "assistant", content: data.answer || data.message || "No answer returned.", result: data }]);
      if (data.status !== "success") setError(data.message || "The assistant could not complete this request.");
      setApiStatus("online");
    } catch (err) {
      const message = err.message?.includes("Failed to fetch")
        ? "Cannot reach the backend. Start FastAPI at http://127.0.0.1:8000 and check the frontend API URL."
        : (err.message || "Something went wrong.");
      setError(message);
      setMessages((prev) => [...prev, { role: "user", content: clean }, { role: "assistant", content: message, result: { status: "error", message } }]);
    } finally { setLoading(false); }
  }

  function newChat() {
    const next = window.crypto?.randomUUID?.() || `session-${Date.now()}`;
    setSessionId(next); window.localStorage.setItem("nlbi-session-id", next);
    setMessages([]); setQuestion(""); setError("");
  }

  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark">DC</div><div><strong>Data Compass</strong><span>Natural language analytics</span></div></div>
      <button className="new-chat-button" onClick={newChat}><span>＋</span> New conversation</button>
      <div className="side-label">WORKSPACE</div>
      <div className="database-card">
        <div className="database-card-top"><span className={`connection-dot ${apiStatus}`}/><span>{apiStatus === "online" ? "Connected" : apiStatus === "checking" ? "Checking" : "Unavailable"}</span></div>
        <strong>{database?.display_name || "Database"}</strong>
        <small>{database?.database_type || "—"} · {database?.table_count ?? "—"} tables</small>
        <button className="connect-button" onClick={() => setShowDatabaseDialog(true)}>Manage database</button>
      </div>
      <button className="context-link" onClick={() => setShowExplorer((value) => !value)}>
        {showExplorer ? "Hide database explorer" : `Explore all tables (${database?.table_count ?? 0})`}
      </button>
      {showExplorer && <DatabaseExplorer profile={databaseProfile} />}
      <div className="side-label">SUGGESTED QUESTIONS</div>
      <div className="example-list">{EXAMPLES.slice(0, 5).map((example) => <button key={example} className="example-button" onClick={() => setQuestion(example)}>{example}</button>)}</div>
      <div className="sidebar-bottom"><div className={`connection-dot ${apiStatus}`}/><div><strong>{apiStatus === "online" ? "API operational" : apiStatus === "checking" ? "Checking API…" : "API unavailable"}</strong><span>{config ? `${config.provider} · ${config.model || "local rules"}` : "Local service"}</span></div></div>
      <button className="context-link" onClick={() => setShowContext((value) => !value)}>{showContext ? "Hide business context" : "View business context"}</button>
      {showContext && <div className="context-box"><p>{context?.database_description || "Schema metadata is discovered from the active database."}</p>{Object.entries(context?.metrics || {}).map(([name, description]) => <p key={name}><b>{name}</b><br/>{description}</p>)}</div>}
    </aside>

    <main className="main-panel">
      <header className="topbar"><div><p className="eyebrow">GENAI · BUSINESS INTELLIGENCE</p><h1>Ask your data.</h1><p className="subtitle">Explore your database with natural language, visual analysis, and transparent SQL.</p></div>
        <div className="topbar-status"><span className={`status-pill ${apiStatus}`}>{apiStatus === "online" ? "API online" : apiStatus === "checking" ? "Connecting" : "API unavailable"}</span><span>{successfulCount} successful {successfulCount === 1 ? "query" : "queries"}</span></div>
      </header>

      <section className={`chat-area ${messages.length ? "has-messages" : ""}`}>
        {messages.length === 0 && <div className="welcome"><div className="welcome-icon">✦</div><p className="section-eyebrow">YOUR DATA, IN PLAIN LANGUAGE</p><h2>What would you like to find out?</h2><p>Connect a local SQL database, ask a question, and explore the answer through charts and data tables.</p><div className="suggestion-grid">{EXAMPLES.slice(0, 4).map((example) => <button key={example} onClick={() => setQuestion(example)}>{example}<span>↗</span></button>)}</div></div>}
        {messages.map((message, index) => message.role === "user" ? <div className="message-row user-row" key={`user-${index}`}><div className="user-avatar">You</div><div className="user-bubble">{message.content}</div></div> : <div className="message-row assistant-row" key={`assistant-${index}`}><div className="assistant-avatar">DC</div><div className="assistant-message">
          {message.result?.status === "success" ? <>
            <div className="answer-head"><span className="answer-label">DATABASE-BACKED ANSWER</span><span className="success-pill">Success</span></div>
            <h2 className="answer-text">{message.result.answer || message.content}</h2>
            {message.result.resolved_question && message.result.resolved_question !== message.result.question && <p className="resolved-question">Interpreted as: {message.result.resolved_question}</p>}
            <div className="answer-stats"><div><span>Intent</span><strong>{message.result.intent?.intent || "—"}</strong></div><div><span>Rows returned</span><strong>{message.result.execution?.row_count ?? "—"}</strong></div><div><span>Chart</span><strong>{CHART_LABELS[message.result.visualization?.chart_type] || message.result.visualization?.chart_type || "Table"}</strong></div><div><span>Groundedness</span><strong className={message.result.answer_evaluation?.grounded ? "good-text" : "bad-text"}>{message.result.answer_evaluation?.grounded ? "Verified" : "Review"}</strong></div></div>
            {message.result.query_plan && <div className="tables-used"><span>Tables used</span><strong>{[message.result.query_plan.table, ...(message.result.query_plan.joins || []).map((join) => join.to_table)].filter(Boolean).filter((name, i, names) => names.indexOf(name) === i).join(" · ") || message.result.query_plan.table}</strong><small>Catalog contains {message.result.database_profile?.table_count ?? database?.table_count ?? "—"} accessible tables/views</small></div>}
            <Visualization result={message.result}/><ResultDetails result={message.result}/>
          </> : <div className="assistant-error"><div className="error-title">{message.result?.status === "blocked" ? "Request blocked" : "Request could not be completed"}</div><p>{message.result?.message || message.content}</p>{message.result?.stage && <span>Stage: {message.result.stage}</span>}</div>}
        </div></div>)}
        {loading && <div className="message-row assistant-row"><div className="assistant-avatar">DC</div><div className="thinking-card"><span className="spinner"/> Running the analysis…<small>Local supported queries are handled without a model call where possible.</small></div></div>}
      </section>

      <div className="composer-wrap"><div className="composer"><textarea value={question} onChange={(event) => setQuestion(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); askQuestion(); } }} placeholder="Ask a question about your business data…" rows={2} disabled={loading} aria-label="Your business question"/>
        <div className="composer-footer"><span>Enter to send · Shift + Enter for a new line</span><button onClick={() => askQuestion()} disabled={loading || !question.trim()}>{loading ? "Analyzing…" : "Ask data ↗"}</button></div></div>
        {error && <div className="inline-error">{error}</div>}
        <p className="footer-note">The assistant uses read-only queries. Verify important business decisions and follow your organisation's data-access policies.</p>
      </div>
    </main>
    <DatabaseDialog open={showDatabaseDialog} onClose={() => setShowDatabaseDialog(false)} onConnected={async (db) => { setDatabase(db); setApiStatus("online"); newChat(); await refreshConnection(); }} currentDatabase={database}/>
  </div>;
}

createRoot(document.getElementById("root")).render(<React.StrictMode><App/></React.StrictMode>);
